RECORD = {
    "id": "JAH-NMS5-000001",
    "name": "Juma",
    "kind": "first-name",
    "meaning": "Juma is a masculine given name in Swahili. Meaning: Friday. Given to Friday-born boys."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Jum")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

